<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/include/clinical.php';hms_start_session();hms_require_role('patient');$ready=hms_stage6_ready($con);$rows=$ready?hms_db_query($con,'SELECT h.id,h.issue_date,d.doctorName,COUNT(i.id) medicines FROM prescription_headers h JOIN doctors d ON d.id=h.doctor_id JOIN prescription_items i ON i.prescription_id=h.id WHERE h.patient_user_id=? GROUP BY h.id ORDER BY h.id DESC',[(int)$_SESSION['id']]):null;?>
